<?php require_once '../includes/auth.php';require_once '../config/uploads.php';require_once '../config/phone.php';$id=(int)($_GET['id']??0);$slug=preg_replace('/[^a-z0-9-]/','',strtolower($_GET['slug']??''));$q=$pdo->prepare('SELECT p.*,s.name AS store_name,s.whatsapp_number FROM products p JOIN stores s ON s.id=p.store_id JOIN users u ON u.id=s.user_id WHERE p.id=? AND s.slug=? AND p.available=1 AND p.moderation_status=? AND u.account_status=?');$q->execute([$id,$slug,'approved','active']);$p=$q->fetch();if(!$p)exit('Product not found');$sellerWhatsApp=normalize_nigerian_whatsapp($p['whatsapp_number']??'');if($_SERVER['REQUEST_METHOD']==='POST'){$_SESSION['cart'][$id]=($_SESSION['cart'][$id]??0)+max(1,min(99,(int)$_POST['quantity']));go('/public/cart.php?slug='.urlencode($slug));}$title=$p['name'];require '../includes/header.php';?><div class="card col-lg-7"><?php if($p['image']):?><a href="<?=e($uploadUrl . '/' . $p['image'])?>" target="_blank" rel="noopener" aria-label="View full-size <?=e($p['name'])?>"><img class="card-img-top" style="max-height:360px;object-fit:cover;cursor:zoom-in" src="<?=e($uploadUrl . '/' . $p['image'])?>" alt="<?=e($p['name'])?>"></a><div class="text-muted small px-3 pt-2">Tap the image to view it full size.</div><?php endif;?><div class="card-body"><div class="d-flex flex-wrap justify-content-between align-items-start gap-2"><div><div class="text-muted small mb-1">Sold by <?=e($p['store_name'])?></div><h1><?=e($p['name'])?></h1></div><?php if($sellerWhatsApp):?><a class="btn btn-success" href="https://wa.me/<?=e($sellerWhatsApp)?>?text=<?=urlencode('Hello, I am interested in '.$p['name'].' from your Choosery store.')?>" target="_blank" rel="noopener">Contact Seller</a><?php endif;?></div><p><?=e($p['description'])?></p><p><?=e($p['variations'])?></p><h3><?=money($p['price'])?></h3><?php if(!$sellerWhatsApp):?><div class="alert alert-warning">The seller has not provided a valid WhatsApp number yet.</div><?php endif;?><form method="post"><input class="form-control" type="number" name="quantity" min="1" max="99" value="1"><button class="btn btn-success mt-2">Add to cart</button></form></div></div><?php require '../includes/footer.php';?>